import pg from 'pg';
import {PostgresAgentSharedCost,SqliteAgentTokenBudget,AgentBudgetRecovery,createBudgetHttpsVerifier} from '../../dist/index.js';
const {APP_MIXER_TEST_POSTGRES_URL:url,APP_MIXER_TEST_SCHEMA:schema,APP_MIXER_TEST_DB:path,APP_MIXER_TEST_PROVIDER:provider,APP_MIXER_TEST_CALL_ID:callId}=process.env,scope={tenantId:'t',agentId:'agent'},actor={tenantId:'t',principalId:'operator'},target={scope,runId:'run',maxTokens:100},pool=new pg.Pool({connectionString:url,options:`-c search_path=${schema}`});
const transaction=async operation=>{const client=await pool.connect();try{await client.query('BEGIN');const result=await operation((sql,args)=>client.query(sql,args));await client.query('COMMIT');return result;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}};
const ledger=new PostgresAgentSharedCost({enabled:true,scope:{tenantId:'t',budgetId:'cycle',currency:'USD',maxMicros:1000},query:(sql,args)=>pool.query(sql,args),transaction,authorize:()=>true}),budget=new SqliteAgentTokenBudget(path,{scope,runId:'run',leaseToken:'retired-token',maxTokens:100,cost:{currency:'USD',maxMicros:1000},clock:()=>110});
try{const verify=createBudgetHttpsVerifier({target,url:provider+'/lookup',bearerToken:'a'.repeat(32),timeoutMs:5000,maxPending:1,interpret:(body,context)=>body&&body.found===true&&body.callId===context.callId&&body.currency===context.cost?.currency?{usedTokens:body.usedTokens,usedCostMicros:body.usedCostMicros}:undefined}),recovery=new AgentBudgetRecovery({budget,target,sharedCost:ledger,authorize:()=>true,verify});const outcome=await recovery.reconcile(actor,callId,'provider-case');process.send({outcome,local:budget.get(callId),cost:budget.getCost(callId),evidence:budget.reconciliationHistory()});}catch(error){process.send({error:String(error)});process.exitCode=1;}finally{budget.close();await pool.end();}
